"""Gradient-mode contexts/decorators for one isolated numerical runtime."""
import functools
import inspect
import sys

from . import _state


def is_grad_enabled():
    return _state._grad_enabled


class _GradContext:
    def _fresh(self):
        return type(self)()

    def __call__(self, function):
        if not callable(function):
            raise TypeError('A gradient-mode decorator requires a callable')
        if inspect.isgeneratorfunction(function):
            @functools.wraps(function)
            def generator(*args, **kwargs):
                iterator = function(*args, **kwargs)
                advance = lambda: next(iterator)
                while True:
                    try:
                        with self._fresh():
                            value = advance()
                    except StopIteration as done:
                        return done.value
                    try:
                        request = yield value
                    except GeneratorExit:
                        with self._fresh():
                            iterator.close()
                        raise
                    except BaseException:
                        error = sys.exc_info()[1]
                        advance = lambda error=error: iterator.throw(error)
                    else:
                        advance = lambda request=request: iterator.send(request)
            return generator
        @functools.wraps(function)
        def wrapped(*args, **kwargs):
            with self._fresh():
                return function(*args, **kwargs)
        return wrapped


