        half=np.asarray(.5,dtype=y.dtype)
        with np.errstate(over='ignore',invalid='ignore'):
            value=(y._data.sum(axis=dim)-(np.take(y._data,0,axis=dim)+np.take(y._data,-1,axis=dim))*half)*step
