    average = (y[tuple(left)] + y[tuple(right)]) / 2
    x = wrap(x)
    if not x.ndim or x.ndim > y.ndim or x.dtype.kind not in 'fc':
        raise _errors.BrowserUnsupported('trapezoid coordinates require floating tensors of supported rank')
